import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BWuWLRhz.js";const l=JSON.parse('{"title":"Architecture Decision Index","description":"","frontmatter":{},"headers":[],"relativePath":"prds/01-project-management.md","filePath":"prds/01-project-management.md","lastUpdated":1785228410000}'),n={name:"prds/01-project-management.md"};function o(d,e,c,s,h,u){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="architecture-decision-index" tabindex="-1">Architecture Decision Index <a class="header-anchor" href="#architecture-decision-index" aria-label="Permalink to &quot;Architecture Decision Index&quot;">​</a></h1><p><strong>Status:</strong> Approved foundation; domain and package reviews are ongoing<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This file is the navigation point for Archie&#39;s target architecture. It is deliberately short. Architectural decisions are separated by domain or requirement so an implementation task can load only the rules governing its scope.</p><p>Implementers MUST read the decision document for the domain or requirement they are changing. They MUST NOT infer permission to change neighbouring domains from a broader restructuring objective.</p><h2 id="global-invariants" tabindex="-1">Global invariants <a class="header-anchor" href="#global-invariants" aria-label="Permalink to &quot;Global invariants&quot;">​</a></h2><ul><li>Organise code around cohesive application responsibilities, not generic technical mechanisms.</li><li>Domains own their behaviour, vocabulary, state, commands, events, policy implementations, runtime settings, and required service contracts.</li><li>Domains do not depend on infrastructure or manipulate another domain.</li><li><code>internal/app</code> owns composition; <code>cmd/*</code> remains thin.</li><li>Cross-domain work uses an explicitly owned command, event, or approved shared contract.</li><li>Process boundaries are deployment choices and do not determine source-code ownership.</li><li>Existing package names and boundaries have no presumption of survival.</li></ul><p>The words <strong>MUST</strong>, <strong>MUST NOT</strong>, <strong>SHOULD</strong>, and <strong>MAY</strong> are normative.</p><h2 id="decision-documents" tabindex="-1">Decision documents <a class="header-anchor" href="#decision-documents" aria-label="Permalink to &quot;Decision documents&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Authoritative document</th></tr></thead><tbody><tr><td>Repository layout, domains, composition, deployments, and optional material</td><td><a href="/architecture/organisation">architecture/organisation.md</a></td></tr><tr><td>Dependency direction, domain contracts, infrastructure, commands, events, and wire contracts</td><td><a href="/architecture/dependencies-and-contracts">architecture/dependencies-and-contracts.md</a></td></tr><tr><td>External configuration, runtime settings, and dissolution of <code>internal/config</code></td><td><a href="/architecture/configuration">architecture/configuration.md</a></td></tr><tr><td>Persistent actor identity, ownership, lifecycle, and attribution</td><td><a href="/architecture/identity">architecture/identity.md</a></td></tr><tr><td>Agent definitions, workflows, workflow executions, tools, and worker boundaries</td><td><a href="/architecture/agent-system">architecture/agent-system.md</a></td></tr><tr><td>Personal-assistant interactions, messaging channels, and optional promotion into durable work</td><td><a href="/architecture/messaging-and-work-intake">architecture/messaging-and-work-intake.md</a></td></tr><tr><td>Shared policy evaluation and domain-owned policy semantics</td><td><a href="/architecture/policy">architecture/policy.md</a></td></tr><tr><td>Safe source/configuration changes, health supervision, and recovery</td><td><a href="/architecture/safe-change-and-recovery">architecture/safe-change-and-recovery.md</a></td></tr><tr><td>Plugin framework, plugin implementations, and extension isolation</td><td><a href="/architecture/plugins-and-extensions">architecture/plugins-and-extensions.md</a></td></tr><tr><td>Generated references, deprecations, and changelog generation</td><td><a href="/architecture/generated-documentation">architecture/generated-documentation.md</a></td></tr><tr><td>Remaining package destinations, data migrations, runtime cutover, and completion criteria</td><td><a href="/architecture/migration-decisions">architecture/migration-decisions.md</a></td></tr><tr><td>Domain/feature research, design interview, and required handoff</td><td><a href="/architecture/package-review">architecture/package-review.md</a></td></tr></tbody></table><h2 id="deferred-decisions" tabindex="-1">Deferred decisions <a class="header-anchor" href="#deferred-decisions" aria-label="Permalink to &quot;Deferred decisions&quot;">​</a></h2><p>The remaining package-placement, data-migration, shared-mechanics, process- boundary, and cutover decisions are maintained in <a href="/architecture/migration-decisions">architecture/migration-decisions.md</a>.</p><p>Each decision is made in its focused document after code-grounded review.</p>',13)])])}const p=t(n,[["render",o]]);export{l as __pageData,p as default};
